// Parse Slack Interactivity payload (x-www-form-urlencoded)
// Slack sends { payload: "{...json...}" } in the body

const body = $json.body || $json;
const raw = body.payload;
if (!raw) {
  return [{ json: { has_error: true, error: 'Missing payload in Slack request', body } }];
}

const payload = typeof raw === 'string' ? JSON.parse(raw) : raw;
const action = payload.actions?.[0];

if (!action) {
  return [{ json: { has_error: true, error: 'No actions[] in payload', payload } }];
}

const action_id = action.action_id; // dlq_replay | dlq_resolve
const dlq_event_id = action.value;  // uuid
const user_id = payload.user?.id;
const user_name = payload.user?.username || payload.user?.name;
const response_url = payload.response_url;

return [{
  json: {
    has_error: false,
    action_id,
    dlq_event_id,
    user_id,
    user_name,
    response_url,
    payload
  }
}];

